const metadataFor = (modelName: string, fieldName: string): { logical_type: string; description: string } => {
  const key = `${modelName}.${fieldName}`;
  const metadataTable = authoritativeModelFieldMetadata as Readonly<Record<string, { logical_type: string; description: string }>>;
  const metadata = metadataTable[key]
    ?? (modelName.endsWith("Record") ? metadataTable[`RecordEnvelope.${fieldName}`] : undefined);
  if (!metadata) throw new Error(`Missing authoritative field metadata for ${key}`);
  const inheritedKey = modelName.endsWith("Record") ? `RecordEnvelope.${fieldName}` : "";
  const inheritedMetadata = inheritedKey ? metadataTable[inheritedKey] : undefined;
  const inheritedLogicalType = exactLogicalTypes[inheritedKey] ?? inheritedMetadata?.logical_type;
  const logical_type = exactLogicalTypes[key] ?? (inheritedLogicalType ?? metadata.logical_type);
  return { logical_type, description: exactDescriptions[key] ?? exactDescriptions[inheritedKey] ?? inheritedMetadata?.description ?? metadata.description };
};
const logicalTypeFor = (modelName: string, fieldName: string): string => metadataFor(modelName, fieldName).logical_type;
const descriptionFor = (modelName: string, fieldName: string): string => metadataFor(modelName, fieldName).description;
const modelField = (name: string, presence: "required" | "optional" = "required", source = "decisions/01-universal-data-model.md", modelName = "Model"): ModelFieldContract => {
  // Additional model tables are normalized with their owning model name
  // below. Avoid constructing a synthetic `Model.*` authority key here.
  if (modelName === "Model") return { name, presence, description: "", source, logical_type: "Text" };
  return { name, presence, description: descriptionFor(modelName, name), source, logical_type: logicalTypeFor(modelName, name), ...exactFieldConstraints[`${modelName}.${name}`] };
};

